u76ee\u524d\u4ec5\u6765\u81ea\u5916\u90e8\u8bb0\u5fc6\uff08TorchOpt \u8bba\u6587/\u6559\u7a0b\uff09\uff0c\u672c\u5730\u65e0\u6cd5\u6838\u5b9e\uff0c\u6267\u884c\u671f\u987b\u5148\u53d6\u5f97\u6587\u6863\u539f\u6587", "\u6570\u503c\u7a33\u5b9a\u6027\u201c\u6539\u5584\u201d\u7684\u53ef\u64cd\u4f5c\u5b9a\u4e49\u9700\u7531\u7814\u7a76\u8005/\u4efb\u52a1\u65b9\u786e\u8ba4\uff0c\u672c\u8bbe\u8ba1\u7ed9\u51fa\u7684\u76f8\u5bf9\u8bef\u5dee+bootstrap CI \u5224\u636e\u4ec5\u4e3a\u63d0\u6848", "\u6267\u884c\u671f\u5047\u8bbe\u6709\u53ef\u7528\u7684 torch/torchopt \u5b89\u88c5\u9014\u5f84\uff08\u7f51\u7edc\u6216\u79bb\u7ebf\u7f13\u5b58\uff09\u4e0e\u53d7\u652f\u6301\u7684 Python \u7248\u672c\uff1b\u5f53\u524d\u73af\u5883\u4e0d\u6ee1\u8db3", "\u7ed3\u679c\u65b9\u5411\uff08\u66f4\u5feb/\u66f4\u7a33\uff09\u4e0d\u9884\u8bbe\uff1b\u4e00\u9636\u5bf9\u7167\u4efb\u52a1\u4f5c\u4e3a\u96f6\u5047\u8bbe\u81c2\u9884\u671f\u65e0\u5dee\u5f02"], "uncertainties": ["TorchOpt \u771f\u5b9e API \u540d\u79f0\u3001\u7b7e\u540d\u4e0e\u662f\u5426\u5b58\u5728\u53ef\u914d\u7f6e\u7684\u4e2d\u95f4\u91cf\u590d\u7528\u5f00\u5173\uff0c\u5728\u672a\u83b7\u5f97\u6e90\u7801/\u6587\u6863\u524d\u5b8c\u5168\u4e0d\u786e\u5b9a", "torchopt \u4e0e torch\u3001Python 3.14 \u7684\u7248\u672c\u517c\u5bb9\u6027\u672a\u77e5\uff083.14 \u8fc7\u65b0\u53ef\u80fd\u5bfc\u81f4\u65e0\u6cd5\u5b89\u88c5\uff09", "\u65e0 GPU \u65f6\u201c\u5cf0\u503c\u663e\u5b58\u201d\u6307\u6807\u9000\u5316\u4e3a CPU RSS/\u5206\u914d\u8ba1\u6570\uff0c\u80fd\u5426\u590d\u73b0\u8bba\u6587\u7ea7\u522b\u7684\u5185\u5b58\u5dee\u8ddd\u4e0d\u786e\u5b9a", "K-FAC/\u534f\u65b9\u5dee\u7c7b\u7b97\u5b50\u5728 TorchOpt \u4fa7\u662f\u5426\u6709\u5bf9\u5e94\u5b9e\u73b0\u672a\u77e5\uff0c\u8be5\u81c2\u53ef\u80fd\u88ab\u5254\u9664", "\u4e8c\u9636\u4efb\u52a1\u5728 CPU \u73a9\u5177\u89c4\u6a21\u4e0b\u6307\u6807\u5dee\u8ddd\u662f\u5426\u8d85\u8fc7\u566a\u58f0\u6c34\u5e73\uff0c\u9700\u5148\u505a\u5c0f\u6837\u672c\u9884\u8bd5\uff08\u6267\u884c\u671f\uff09\u624d\u80fd\u786e\u5b9a