5\u6570\u503c/\u6027\u80fd\u7ed3\u8bba\u90fd\u65e0\u6cd5\u5728\u672c\u73af\u5883\u6267\u884c\uff0c\u53ea\u80fd\u505c\u7559\u5728\u8bbe\u8ba1\u5c42\u9762\uff08\u8be6\u89c1\u53ef\u884c\u6027\u6761\u76ee\uff09\u3002\n\n\u3010B\uff5c\u63a8\u6d4b\uff08\u6765\u81ea\u516c\u5f00\u6587\u6863\u8bb0\u5fc6\uff0c\u672c\u73af\u5883\u4e0d\u53ef\u6838\u5b9e\uff0c\u4e00\u5f8b\u6309\u5047\u8bbe\u5bf9\u5f85\uff09\u3011\n- TorchOpt \u662f PyTorch \u539f\u751f\u51fd\u6570\u5f0f\u4f18\u5316\u5668\u5e93\uff08Optax \u79fb\u690d\uff09\uff0c\u5176\u8bba\u6587\uff08arXiv:2404.16815\uff0c\u8bb0\u5fc6\u6240\u81f4\uff0c\u672a\u6838\u5b9e\uff09\u58f0\u79f0\u51fd\u6570\u5f0f\u5fae\u5206\u53d8\u6362\u652f\u6301\u9ad8\u9636\u5bfc/\u5143\u5b66\u4e60\u573a\u666f\u3002\n- \u300c\u663e\u5f0f\u68af\u5ea6\u5fae\u5206 API\u300d\u6700\u53ef\u80fd\u6307 torchopt.grad / torchopt.value_and_grad\uff08\u57fa\u4e8e torch.func.functional_call \u7684\u51fd\u6570\u5f0f\u53d8\u6362\uff09\uff0c\"\u590d\u7528\u4e2d\u95f4\u91cf\u3001\u6700\u5c0f\u5316\u5206\u914d\" \u662f\u5ba3\u4f20\u6027\u8bbe\u8ba1\u610f\u56fe\uff1bgradient_as_tuple \u8fd9\u4e00\u5177\u4f53\u5f00\u5173\u540d\u65e0\u6cd5\u6838\u5b9e\uff0c\u6807\u8bb0\u4e3a\u5047\u8bbe\uff0c\u6267\u884c\u671f\u5fc5\u987b\u4ee5\u5b9e\u9645\u6e90\u7801/\u6587\u6863\u786e\u8ba4\u771f\u5b9e\u63a5\u53e3\u540d\u4e0e\u8bed\u4e49\u540e\u624d\u80fd\u5b9a\u4e49\u5b9e\u9a8c\u81c2\u3002\n\n\u4e8c\u3001\u5bf9\u7167\u57fa\u7ebf\u5019\u9009\uff08\u672c\u5730\u5747\u4e0d\u53ef\u6838\u5b9e\uff0c\u6765\u6e90=\u516c\u5f00\u6587\u6863\u77e5\u8bc6\uff0c\u6267\u884c\u671f\u9700\u9a8c\u8bc1\u5b58\u5728\u6027\u4e0e\u7248\u672c\u517c\u5bb9\uff09\n- torch.autograd.backward / torch.autograd.grad\uff08create_graph=True \u53cc\u53cd\u5411\uff09\u2014\u2014\u6807\u51c6\u57fa\u7ebf\u3002\n- torch.func \u7ec4\u5408\u5b50\uff08grad/vmap/functional_call/hessian\uff09\u2014\u2014\u4e0e TorchOpt \u540c\u4e00\u5e95\u5ea7\uff0c\u7528\u4e8e\u5265\u79bb\u300c\u51fd\u6570\u5f0f\u98ce\u683c\u300d\u4e0e\u300c\u663e\u5f0f\u5fae\u5206\u5b9e\u73b0\u300d\u4e24\u4e2a\u6df7\u6742\u56e0\u7d20\u3002\n- \u53cc\u53cd\u5411 vs \u663e\u5f0f\u5c55\u5f00\uff08unfold/JVP \u7d2f\u52a0\u3001R\u2194\u53cd\u5411\u6a21\u5f0f\u8f6c\u6362\uff09\uff1aPyTorch \u5b98\u65b9\u6587\u6863\u4e2d bilevel optimization / BilevelOptim \u793a\u4f8b\uff082.4+\uff0c\u8bb0\u5fc6\u6240\u5f15\uff0c\u9700\u6838\u5b9e\uff09\u660e\u786e\u5bf9\u6bd4 double-backward \u4e0e unfold \u6280\u5de7\u7684\u5185\u5b58/\u6570\u503c\u6743\u8861\u2014\u2014\u8fd9\u662f\u4e0e\u672c\u95ee\u9898\u6700\u540c\u6784\u7684\u516c\u5f00\u5bf9\u7167\u3002\n- \u9700\u8981\u4e2d\u95f4\u91cf\u7684\u573a\u666f\u5019\u9009\uff1ahypergradient\uff08\u6b63\u5219\u7cfb\u6570\u5916\u5c42\u66f4\u65b0\uff09\u3001MAML \u4e00\u9636/\u4e8c\u9636\uff08learn2learn \u6216 TorchOpt \u81ea\u5e26\u6559\u7a0b\uff09\u3001higher \u5e93\uff08\u5df2\u5f52\u6863\uff09\u3001learned_optimizers\u3001K-FAC \u7c7b\u534f\u65b9\u5dee/\u66f2\u7387\u7b97\u5b50\uff08\u53ef\u9009\uff0c\u82e5 TorchOpt \u4fa7\u65e0\u5bf9\u5e94\u5b9e\u73b0\u5219\u5254\u9664\uff0c\u907f\u514d\u6253\u7a7a\u9776\uff09\u3002\n\n\u4e09\u3001\u62df\u5b9a\u65b9\u6848\u9aa8\u67b6\uff08\u975e\u7ed3\u8bba\uff09\n1. \u4e24\u4fa7\u5b9a\u4e49\u4e0e single-factor \u63a7\u5236\uff1a\n   - A \u81c2\uff1atorchopt.grad / value_and_grad\uff08\u6216\u5176\"\u590d\u7528\u4e2d\u95f4\u91cf\"\u914d\u7f6e\uff0c\u4ee5\u6838\u5b9e\u540e\u7684\u771f\u5b9e\u5f00\u5173\u4e3a\u51c6\uff09\u3002\n   - B \u81c2\uff1atorch.autograd.grad(create_graph=True) \u53cc\u53cd\u5411\uff0c\u5fc5\u8981\u65f6\u52a0 B2 \u81c2 = unfold/\u663e\u5f0f\u5c55\u5f00\u7eaf torch \u7248\u3002\n   - \u552f\u4e00\u5dee\u522b = \u6c42\u68af\u5ea6\u7684\u5165\u53e3\u51fd\u6570\u4e0e\u56fe\u7b56\u7565\uff1b\u524d\u5411\u8ba1\u7b97\u5728\u4e24\u4fa7\u5171\u7528\u540c\u4e00\u51fd\u6570\u5f0f forward\uff08\u540c\u4e00 functional_call \u4ee3\u7801\u8def\u5f84\uff09\uff0c\u540c\u4e00\u6a21\u578b\u521d\u59cb\u5316\u3001\u540c\u6279\u6570\u636e\u3001\u540c dtype\u3001\u540c\u7ebf\u7a0b\u6570\uff08torch.set_num_threads \u56fa\u5b9a + taskset \u7ed1\u6838\uff0c\u907f\u514d 224 \u6838\u8c03\u5ea6\u566a\u58f0\uff09\u3001\u540c\u5206\u914d\u5668\u8bbe\u7f6e\u3002\n2. \u6307\u6807\u4e0e\u65f6\u673a\uff1a\n   - \u65f6\u95f4\uff1a\u9884\u70ed \u226510 \u6b21\u540e\u91cd\u590d \u226550 \u6b21\uff0c\u62a5\u4e2d\u4f4d\u6570\u4e0e 5/95 \u5206\u4f4d\uff08perf_counter\uff09\uff0c\u5e76\u5206\u89e3 fwd/bwd/step \u6bb5\uff1bGPU \u7528 CUDA event\uff0cCPU \u7528\u5899\u949f\u3002\n   - \u5185\u5b58\uff1aGPU \u4fa7 torch.cuda.max_memory_allocated/reserved\uff1bCPU \u4fa7 VmHWM(RSS) + torch.profiler \u8bb0\u5f55\u5206\u914d\u4e8b\u4ef6\u8ba1\u6570\uff08\u5cf0\u503c\u4e0e\u7a33\u6001\u3001\u5206\u914d\u6b21\u6570\uff09\u3002\n   - \u6570\u503c\u7a33\u5b9a\u6027\uff1a\u4ee5 float64\uff08\u5fc5\u8981\u65f6\u5d4c\u5957\u66f4\u9ad8\u7cbe\u5ea6\u6821\u9a8c\uff09\u53c2\u8003\u503c\u7684\u76f8\u5bf9 L2 \u8bef\u5dee\u4e3a\u4e3b\u6307\u6807\uff1b\u8f85\u52a9\u6307\u6807\uff1aNaN/Inf \u51fa\u73b0\u7387\u3001Hessian/Jacobian \u6761\u4ef6\u6570\u5206\u5c42\u3001\u5185\u5916\u5c42\u6b65\u957f\u654f\u611f\u6027\u626b\u63cf\u3002\"\u6539\u5584\" \u7684\u53ef\u64cd\u4f5c\u5b9a\u4e49\u9700\u60a8\u7ed9\u5b9a\u6216\u7531\u672c\u8bbe\u8ba1\u8349\u6848\u63d0\u4ea4\u540e\u5546\u5b9a\uff08\u5efa\u8bae\uff1a\u6309\u79cd\u5b50\u914d\u5bf9\u7684\u76f8\u5bf9\u8bef\u5dee\u5dee\u503c\u4e2d\u4f4d\u6570<0 \u4e14 bootstrap 95% CI \u4e0d\u542b 0\uff0c\u4e14\u4e24\u4fa7\u5747\u65e0 NaN/Inf\uff09\u3002\n3. \u4efb\u52a1\u4e0e\u89c4\u6a21\uff1a\n   - \u5f3a\u4e8c\u9636/\u5927\u4e2d\u95f4\u91cf\u4efb\u52a1\uff1aMAML \u5f0f\u4e8c\u9636\u5143\u5b66\u4e60\uff08sinusoid \u8d77\u6b65\uff0cOmniglot \u6269\u5c55\uff1b\u5185\u5faa\u73af\u5c55\u5f00\u6df1\u5ea6 K \u662f\u4e2d\u95f4\u91cf\u89c4\u6a21\u65cb\u94ae\uff09+ ridge \u8d85\u68af\u5ea6\u95ee\u9898\uff08\u53ef\u7cbe\u786e\u7b97\u53c2\u8003\u89e3\uff09\u3002\n   - \u4e00\u9636\u5bf9\u7167\u4efb\u52a1\uff08\u7a7a\u5bf9\u7167/\u96f6\u5047\u8bbe\u68c0\u9a8c\uff09\uff1a\u666e\u901a MLP+SGD\uff0c\u9884\u671f\u4e24\u4fa7\u65e0\u5dee\u5f02\uff0c\u7528\u4e8e\u68c0\u6d4b harness \u504f\u5dee\u3002\n   - \u89c4\u6a21\u68af\u5ea6\uff1a\u5bbd\u5ea6 {32,128,512}\u3001\u5c42\u6570 {2,4}\u3001K\u2208{1,5,20}\uff0c\u9884\u671f\u663e\u5b58/\u65f6\u95f4\u6bd4\u968f\u89c4\u6a21\u653e\u5927\u3002\n4. \u7edf\u8ba1\u5904\u7406\uff1a\u6570\u503c\u6307\u6807 \u226510 \u4e2a\u968f\u673a\u79cd\u5b50/\u914d\u7f6e\u3001\u62a5\u544a\u914d\u5bf9\u6548\u5e94\u91cf\uff08Hodges\u2013Lehmann\u3001log-ratio \u5747\u503c\uff09\u4e0e bootstrap CI\uff1b\u65f6\u95f4\u6307\u6807\u56fa\u5b9a\u79cd\u5b50\u3001\u22653 \u6b21\u72ec\u7acb\u8fdb\u7a0b\u91cd\u542f\uff0c\u7981\u5355\u6b21\u7ed3\u8bba\uff1b\u9884\u6ce8\u518c\u4e3b\u6307\u6807\uff08\u5cf0\u503c\u5185\u5b58\u3001\u65f6\u95f4\u4e2d\u4f4d\u6570\u3001\u76f8\u5bf9\u8bef\u5dee\uff09\u540e\u518d\u8dd1\u3002\n5. \u53ef\u884c\u6027\uff08\u5f53\u524d\u73af\u5883\uff09\uff1a\u65e0\u7f51\u7edc + torch/torchopt \u672a\u88c5 + Python 3.14\uff08\u5f53\u524d torch \u8f6e\u5b50\u5927\u6982\u7387\u4e0d\u652f\u6301\uff0c\u6b64\u70b9\u4ea6\u5c5e\u63a8\u6d4b\uff09\u2192 \u672c\u73af\u5883\u5185\u4e00\u884c\u5bf9\u6bd4\u4ee3\u7801\u90fd\u8dd1\u4e0d\u4e86\uff1b\u6267\u884c\u9700\u8981\uff1a(a) \u79bb\u7ebf wheel \u7f13\u5b58\u6216\u7f51\u7edc\uff0c(b) torchopt \u6e90\u7801 checkout \u4ee5\u6838\u5b9e API\uff0c(c) Python \u2264 torch \u652f\u6301\u7248\u672c\u3002\u65e0 GPU \u65f6 GPU \u663e\u5b58\u6307\u6807\u9000\u5316\u4e3a CPU \u5206\u914d\u8ba1\u6570/RSS\uff0c\u89c4\u6a21\u9700\u7f29\u5c0f\u5230\u73a9\u5177\u7ea7\u4f46\u8bbe\u8ba1\u4ecd\u6210\u7acb\u3002\n\n\u56db\u3001\u5173\u952e\u5047\u8bbe\u4e0e\u4e0d\u786e\u5b9a\u4e4b\u5904\n- \u5047\u8bbe 1\uff1a\u300c\u663e\u5f0f\u68af\u5ea6\u68af\u5ea6\u5fae\u5206 API\u300d= torchopt.grad/value_and_grad \u53ca\u5176\u67d0\u590d\u7528\u5f00\u5173\uff1bgradient_as_tuple \u4e4b\u540d\u4e0d\u53ef\u6838\u5b9e\u3002\u82e5\u771f\u5b9e API \u4e0d\u540c\uff0c\u6574\u4e2a A \u81c2\u5b9a\u4e49\u9700\u6539\u3002\n- \u5047\u8bbe 2\uff1a\u300c\u590d\u7528\u4e2d\u95f4\u91cf\u3001\u6700\u5c0f\u5316\u5206\u914d\u300d\u662f\u6587\u6863\u58f0\u660e\u7684\u8bbe\u8ba1\u610f\u56fe\u2014\u2014\u76ee\u524d\u53ea\u80fd\u6765\u81ea\u6211\u7684\u5916\u90e8\u8bb0\u5fc6\uff0c\u975e\u672c\u5730\u6838\u5b9e\uff1b\u6267\u884c\u671f\u7b2c\u4e00\u6b65\u5fc5\u987b\u4ece\u5b98\u65b9 docs/\u8bba\u6587\u63d0\u53d6\u539f\u6587\u5f15\u7528\uff0c\u5426\u5219\u6807\u6ce8\u4e3a\u5f85\u8bc1\u610f\u56fe\u3002\n- \u5047\u8bbe 3\uff1a\u6570\u503c\u7a33\u5b9a\u6027\u300c\u6539\u5584\u300d\u7684\u5b9a\u4e49\u5c1a\u672a\u7531\u4efb\u52a1\u65b9\u7ed9\u5b9a\uff1b\u6211\u4e0d\u9884\u8bbe\u65b9\u5411\u2014\u2014\u6587\u732e\u5148\u9a8c\u53cc\u5411\u5b58\u5728\uff08\u53cc\u53cd\u5411\u5728\u75c5\u6001\u95ee\u9898\u4e0a\u53ef\u80fd\u66f4\u7a33\uff0cunfold \u7701\u5185\u5b58\u4f46\u53ef\u80fd\u66f4\u4e0d\u7a33\uff09\uff0c\u663e\u5f0f\u5b9e\u73b0\u4e5f\u53ef\u80fd\u56e0\u5c11\u4e00\u5c42\u53cd\u4f20\u56fe\u800c\u6539\u53d8\u8bef\u5dee\u7ed3\u6784\u3002\n- \u4e0d\u786e\u5b9a\uff1atorchopt \u4e0e torch \u7248\u672c\u914d\u5bf9\u3001API \u662f\u5426\u4ec5\u5728\u4e3b\u5206\u652f\uff1bK-FAC \u81c2\u662f\u5426\u53ef\u884c\uff1bCPU-only \u4e0b\u4e8c\u9636\u4efb\u52a1\u89c4\u6a21\u662f\u5426\u8db3\u4ee5\u62c9\u5f00\u6307\u6807\u5dee\u8ddd\u3002", "evidence": "1) inspect_repository(/workspace) \u4e0e ls -la \u663e\u793a\u5de5\u4f5c\u533a\u4ec5 task.json\uff1bfind / -maxdepth 4 -iname '*torchopt*' \u65e0\u7ed3\u679c\uff1b/usr/lib/python3/dist-packages \u4e2d grep \u65e0 torch/numpy/jax/autograd \u76f8\u5173\u5305 \u2192 \u65e0\u672c\u5730 TorchOpt \u8d44\u6599\u30022) python3 --version = 3.14.4\uff1bimport torch / torchopt / numpy / jax \u5747 ModuleNotFoundError\uff08\u5df2\u6838\u5b9e\u672a\u5b89\u88c5\uff09\u30023) nproc=224\uff1bfree \u663e\u793a\u7ea6 2TB \u5185\u5b58\uff1b\u73af\u5883\u6807\u6ce8 gpu_enabled=false\u3001network=disabled\uff1bpip download torchopt \u5931\u8d2