\u6cd5\uff08\u9884\u5148\u6ce8\u518c\uff09\uff1a**\n- \u964d\u7ea7 D1\uff1aAPI \u5b58\u5728\u4f46\u65e0\"\u590d\u7528\u4e2d\u95f4\u91cf\"\u5f00\u5173 \u2192 A \u81c2\u5b9a\u4e3a\u8be5 API \u9ed8\u8ba4\u8c03\u7528\uff0c\u95ee\u9898\u6539\u5199\u4e3a\"TorchOpt \u51fd\u6570\u5f0f\u5fae\u5206\u5165\u53e3 vs \u53cc\u53cd\u5411\"\u7684\u540c\u6784\u5bf9\u6bd4\uff0c\"\u590d\u7528\u4e2d\u95f4\u91cf\"\u4ec5\u4f5c\u4e3a\u5f85\u9a8c\u8bc1\u673a\u5236\u89e3\u91ca\uff0c\u4e0d\u5199\u5165\u7ed3\u8bba\u3002\n- \u964d\u7ea7 D2\uff1a\u6e90\u7801\u663e\u793a\u8be5 API \u662f torch.func.grad \u7684\u8584\u5c01\u88c5\uff08\u65e0\u72ec\u7acb\u5b9e\u73b0\uff09\u2192 A \u81c2\u4e0e C \u81c2\u574d\u7f29\uff0c\u4e3b\u5bf9\u6bd4\u6539\u4e3a\u300ctorch.func \u663e\u5f0f\u5c55\u5f00\uff08grad-of-grad / vmap \u7ec4\u5408\uff09vs torch.autograd \u53cc\u53cd\u5411 vs unfold \u624b\u5de5\u5c55\u5f00\u300d\uff0c\u539f\u95ee\u9898\u4e2d\"TorchOpt \u7279\u6709\u6548\u5e94\"\u6539\u5199\u4e3a\"\u65e0\u6cd5\u5f52\u56e0\u4e8e\u5e93\"\uff0c\u5982\u5b9e\u58f0\u660e\u3002\n- \u964d\u7ea7 D3\uff1a\u5b98\u65b9\u65e0\u4efb\u4f55\u5185\u5b58/\u7a33\u5b9a\u6027\u58f0\u660e \u2192 \"\u8bbe\u8ba1\u610f\u56fe\"\u4fdd\u7559\u4e3a\u5047\u8bbe\uff0c\u672c\u5b9e\u9a8c\u53ea\u6d4b\u51c0\u6548\u5e94\uff0c\u4e0d\u68c0\u9a8c\u673a\u5236\u5ba3\u79f0\u3002\n\n---\n\n## 2. \u81c2\u5b9a\u4e49\u4e0e\u5355\u4e00\u56e0\u7d20\u8868\n\n| \u81c2 | \u5b9a\u4e49 | \u89d2\u8272 |\n|---|---|---|\n| A | Gate 0 \u6838\u5b9e\u540e\u7684 TorchOpt \u663e\u5f0f\u5fae\u5206\u5165\u53e3\uff08\u9ed8\u8ba4\u914d\u7f6e + \u82e5\u5b58\u5728\u5219\u5355\u5217\"\u590d\u7528\u5f00\u5173\u5f00/\u5173\"\u4e24\u4e2a\u5b50\u81c2\uff09 | \u5b9e\u9a8c\u81c2 |\n| B1 | `torch.autograd.grad(loss, params, create_graph=True)` \u53cc\u53cd\u5411 | \u6807\u51c6\u57fa\u7ebf\uff08\u4e3b\u5bf9\u7167\uff09 |\n| B2 | \u624b\u5de5 unfold/\u663e\u5f0f\u5c55\u5f00\uff08\u5916\u5c42\u5bf9\u5c55\u5f00\u7684\u5185\u5c42\u8ba1\u7b97\u56fe\u6574\u4f53\u53cd\u4f20\uff1b\u65e0\u5185\u5faa\u73af\u4efb\u52a1\u7528 Jacobian \u663e\u5f0f\u7d2f\u52a0\uff09 | \u673a\u5236\u540c\u6784\u5bf9\u7167\uff1a\u4e0e A \u5171\u4eab\"\u663e\u5f0f\u5c55\u5f00\"\u8fd9\u4e00\u7279\u5f81\uff0c\u7528\u4e8e\u5224\u65ad\u6548\u5e94\u6765\u81ea\"\u663e\u5f0f\"\u8fd8\u662f\u6765\u81ea\"TorchOpt \u5b9e\u73b0\" |\n| C | `torch.func.grad / grad(grad(f)) / vmap + functional_call` | \u7b2c\u4e09\u65b9\uff1a\u5265\u79bb\"\u51fd\u6570\u5f0f\u98ce\u683c\"\u6df7\u6742\u3002\u82e5 A\u2248C \u4e14\u5747\u2260B1\uff0c\u5f52\u56e0\u4e8e\u51fd\u6570\u5f0f\u5b9e\u73b0\u5dee\u5f02\uff1b\u82e5 A\u2248B1 \u4e14\u5747\u2260C\uff0c\u5f52\u56e0\u4e8e\u5c55\u5f00\u7b56\u7565 |\n| N | \u4e00\u9636 MLP+SGD\uff08\u65e0 create_graph\uff09\uff0c\u5206\u522b\u5728 A/B1/C \u5165\u53e3\u4e0b\u8fd0\u884c | \u96f6\u5047\u8bbe\u81c2\uff08\u00a75\uff09 |\n\n**\u4e24\u4fa7\u552f\u4e00\u5141\u8bb8\u5b58\u5728\u7684\u5dee\u522b\uff08\u9010\u9879\u51bb\u7ed3\u6e05\u5355\uff09\uff1a**\n1. \u6c42\u68af\u5ea6\u7684\u5165\u53e3\u8c03\u7528\uff08A/B1/B2/C \u5404\u81ea\u7684\u6c42\u5bfc\u8bed\u53e5\uff09\uff1b\n2. \u7531\u6b64\u9690\u542b\u7684\u53cd\u4f20\u56fe\u6784\u5efa\u7b56\u7565\u3002\n\u5176\u4f59\u5168\u90e8\u5f3a\u5236\u76f8\u540c\uff1a\u540c\u4e00\u51fd\u6570\u5f0f forward\uff08\u540c\u4e00 `functional_call` \u4ee3\u7801\u8def\u5f84\u4e0e\u540c\u4e00\u6743\u91cd pytree \u683c\u5f0f\uff09\uff1b\u540c\u521d\u59cb\u5316\uff08\u79cd\u5b50\u2192\u540c RNG \u6d41\u751f\u6210\u6743\u91cd\uff09\uff1b\u540c\u6279\u6b21\u6570\u636e\uff08\u9884\u751f\u6210\u3001\u843d\u76d8\u3001\u6309\u6821\u9a8c\u548c\u52a0\u8f7d\uff0c\u5404\u81c2\u8bfb\u540c\u4e00\u6587\u4ef6\uff09\uff1b\u540c dtype\uff08\u4e3b\u5b9e\u9a8c float32\uff0c\u53c2\u8003 float64\uff09\uff1b\u540c\u8bbe\u5907\uff1b`torch.set_num_threads` \u56fa\u5b9a\uff08\u5efa\u8bae 8\uff09+ `taskset` \u7ed1\u6838\uff1b\u540c\u5206\u914d\u5668/\u73af\u5883\u53d8\u91cf\uff1b\u540c\u8fed\u4ee3\u6b21\u6570\u4e0e\u4f18\u5316\u5668\uff08SGD/AdamW \u53c2\u6570\u76f8\u540c\uff09\uff1b\u540c Python \u8fdb\u7a0b\u914d\u7f6e\u3002B2 \u81c2\u82e5\u5fc5\u987b\u6539\u5199 forward \u4e3a\u5c55\u5f00\u5f0f\uff0c\u987b\u5148\u505a\u524d\u5411\u8f93\u51fa\u9010\u4f4d\u4e00\u81f4\u65ad\u8a00\uff08float64 \u4e0b atol=0 \u6216 1e-12\uff09\uff0c\u5426\u5219\u4e0d\u5f97\u8fdb\u5165\u8ba1\u65f6\u3002\n\n---\n\n## 3. \u6307\u6807\u4e0e\u6d4b\u91cf\u65f6\u673a\n\n| \u6307\u6807 | \u5b9a\u4e49 | \u6d4b\u91cf\u65f6\u673a | \u91c7\u96c6\u65b9\u5f0f |\n|---|---|---|---|\n| \u4e3b1 \u5cf0\u503c\u5185\u5b58 | GPU\uff1a`max_memory_allocated`/`reserved`\uff1bCPU \u9000\u5316\uff1a\u8fdb\u7a0b\u5cf0\u503c RSS\uff08VmHWM\uff09+ \u5206\u914d\u4e8b\u4ef6\u8ba1\u6570\u4e0e\u5b57\u8282\u6570 | \u9884\u70ed\u7ed3\u675f\u3001\u7a33\u6001\u6d4b\u7a0b\u6bb5\u672b\u8bfb\u53d6/\u6c47\u603b | `torch.cuda.*`\uff08\u82e5\u6709 GPU\uff09\uff1b`resource.getrusage`/`/proc/self/status`\uff1b`torch.profiler(profile_memory=True)` \u7edf\u8ba1\u5206\u914d\u6b21\u6570 |\n| \u4e3b2 \u5355\u6b65\u65f6\u95f4\u4e2d\u4f4d\u6570 | \u4e00\u4e2a meta-step\uff08fwd+\u5185\u5c42\u6c42\u89e3+\u5916\u5c42\u68af\u5ea6+step\uff09\u5899\u949f | \u9884\u70ed 10 \u6b65\u540e\u8fde\u7eed 50 \u6b65 \u00d7 3 \u6b21\u72ec\u7acb\u8fdb\u7a0b\u91cd\u542f | `perf_counter`\uff08CPU\uff09/ CUDA event\uff08GPU\uff09\uff1b\u5206\u6bb5\u8bb0\u5f55 fwd / \u5185\u5c42 / \u5916\u5c42\u5fae\u5206 / \u53c2\u6570\u66f4\u65b0 |\n| \u4e3b3 \u76f8\u5bf9\u8bef\u5dee | \u5404\u81c2\u5916\u5c42\u68af\u5ea6\uff08\u8d85\u68af\u5ea6\uff09\u5bf9 float64 \u53c2\u8003\u7684\u76f8\u5bf9 L2 \u8bef\u5dee | \u6bcf\u914d\u7f6e\u6bcf\u79cd\u5b50\u7b2c 1\u30015\u300110 \u4e2a\u5916\u5c42\u6b65\u5404\u8bb0\u4e00\u6b21\uff08\u65e9\u671f\u653e\u5927\u5dee\u5f02\u654f\u611f\u533a\uff09 | \u540c\u8fdb\u7a0b\u5185\u4ee5 float64 \u91cd\u7b97\u540c\u4e00\u89e3\u6790/\u6570\u503c\u53c2\u8003 |\n| \u6b21-1 \u65f6\u95f4\u5206\u4f4d\u6570 | 5/95 \u5206\u4f4d\u3001IQR | \u540c\u4e0a | \u540c\u4e0a |\n| \u6b21-2 \u6761\u4ef6\u6570 | \u5185\u5