636e\u91cd\u52a0\u6743\uff08\u540c PyTorch \u5b98\u65b9 bilevel \u793a\u4f8b\u8303\u5f0f\uff0cdouble-backward vs unfold\u3010\u8be5\u793a\u4f8b\u5b58\u5728\u6027\u672a\u672c\u5730\u6838\u5b9e\uff0c\u5c5e\u5047\u8bbe\u3011\uff09 | \u5f3a | float64 \u6570\u503c\u53c2\u8003 | \u540c T1 | \u4e0e\u516c\u5f00\u6587\u6863\u8bbe\u7f6e\u540c\u6784\uff0c\u4fbf\u4e8e\u5916\u90e8\u5bf9\u7167 |\n| T4\uff08\u53ef\u9009\uff0cGate 0 \u540e\u53d1\u73b0 TorchOpt \u4fa7\u65e0\u5bf9\u5e94\u5b9e\u73b0\u5373\u5254\u9664\uff09\u534f\u65b9\u5dee/\u66f2\u7387\u7c7b\u7b97\u5b50\uff08K-FAC \u98ce\u683c Kronecker \u56e0\u5b50\u7684\u7279\u5f81\u5206\u89e3\uff09 | \u4e2d | float64 \u53c2\u8003 | \u5c42\u5bbd {64, 256, 1024} | \u4e0d\u5f97\u6253\u7a7a\u9776\uff1a\u4ec5\u5f53 A \u81c2\u6709\u771f\u5b9e\u5bf9\u5e94\u8def\u5f84\u624d\u542f\u7528 |\n| N \u96f6\u5047\u8bbe\u81c2\uff1a\u5408\u6210/\u5c0f\u56fe\u50cf\u4e00\u9636 MLP+SGD | \u65e0 | \u4e0d\u9700\u8981 | \u5bbd\u5ea6 {128, 512} | \u5f3a\u5236\u9879\uff0c\u89c1 \u00a75 |\n\n\u89c4\u6a21\u62a5\u544a\u89c4\u8303\uff1a\u5bf9 K\u3001\u5bbd\u5ea6\u4e24\u4e2a\u8f74\u5404\u51fa\u4e00\u6761 log-log \u7684\u300c\u6307\u6807~\u89c4\u6a21\u300d\u66f2\u7ebf\uff08\u5185\u5b58\u3001\u65f6\u95f4\u5404\u4e00\uff09\uff0c\u6bd4\u8f83\u5404\u81c2\u659c\u7387\u4e0e\u622a\u8ddd\uff1b\u7981\u6b62\u53ea\u62a5\u5355\u70b9\u3002CPU-only \u65f6 T2 \u53d6\u5c0f\u6863\u4f18\u5148\uff08\u5bbd\u5ea6 \u2264128\u3001K \u226410\u3001Omniglot \u6682\u7f13\uff09\uff0c\u89c4\u6a21\u4e0b\u9650\u4f30\u7b97\u89c1 \u00a77 \u68c0\u67e5\u8868\u3002\n\n---\n\n## 5. \u63a7\u5236\u4e0e\u96f6\u5047\u8bbe\u81c2\uff08\u542b\u91cf\u5316\u901a\u8fc7\u5bb9\u5dee\uff09\n\n- N \u81c2\u901a\u8fc7\u5224\u636e\uff08\u9884\u6ce8\u518c\uff09\uff1a\u5728 N \u4efb\u52a1\u4e0a\uff0c\u914d\u5bf9\uff08\u540c\u79cd\u5b50\uff09\u7684 A/B1 \u4e0e C/B1 \u65f6\u95f4\u6bd4\u503c\u7684 bootstrap 95% CI \u5fc5\u987b\u6574\u4f53\u843d\u5165\u7b49\u4ef7\u533a\u95f4 [1/1.05, 1.05]\uff08TOST\uff0c\u5bf9\u6570\u5c3a\u5ea6\u8fb9\u9645 \u00b1ln 1.05\uff09\uff1b\u5cf0\u503c RSS \u76f8\u5bf9\u5dee CI \u843d\u5165 \u00b12% \u6216 < 2\u00d7\u79cd\u5b50\u95f4\u6807\u51c6\u5dee\uff08\u53d6\u8f83\u5bbd\u8005\uff09\u3002\u82e5\u4e0d\u901a\u8fc7 \u2192 \u5224\u5b9a harness/\u5165\u53e3\u5305\u88c5\u672c\u8eab\u6709\u5f00\u9500\uff0c\u6682\u505c\u4e3b\u5b9e\u9a8c\uff0c\u5148\u5f52\u56e0\uff08\u5982\u8f93\u5165\u683c\u5f0f\u8f6c\u6362\u3001pytree \u62f7\u8d1d\uff09\uff0c\u5e76\u628a\u8fd9\u4e2a\u5f00\u9500\u4f5c\u4e3a\u72ec\u7acb\u53d1\u73b0\u5355\u5217\u3002\n- \u524d\u5411\u4e00\u81f4\u6027\u65ad\u8a00\uff1a\u6240\u6709\u81c2\u5728\u6d4b\u524d assert \u524d\u5411\u8f93\u51fa\u4e0e B1 \u5728 float64 \u4e0b\u6700\u5927\u7edd\u5bf9\u5dee \u2264 1e-12\u3002\n- \u987a\u5e8f\u504f\u501a\u63a7\u5236\uff1a\u914d\u7f6e\u5185\u81c2\u7684\u6267\u884c\u987a\u5e8f\u7528\u62c9\u4e01\u65b9\u8f6e\u6362\uff1b\u8fdb\u7a0b\u91cd\u542f\u6253\u6563\u81c2\u987a\u5e8f\u3002\n- \u7ebf\u7a0b/\u7ed1\u6838/\u9891\u7387\u566a\u58f0\uff1a\u56fa\u5b9a\u7ebf\u7a0b\u6570\u3001\u7ed1\u6838\u96c6\u5408\u8bb0\u5f55\u5165\u65e5\u5fd7\uff1b\u6bcf\u6b21\u91cd\u542f\u8bb0\u5f55 CPU \u9891\u7387\u4e0e\u8d1f\u8f7d\u5feb\u7167\u3002\n\n---\n\n## 6. \u7edf\u8ba1\u8ba1\u5212\u4e0e\u5224\u636e\uff08\u542b\u7814\u7a76\u65b9\u88c1\u5b9a\u539f\u6587\u7684\u5de5\u7a0b\u5316\u843d\u5730\uff09\n\n**\u4e3b\u7ec8\u70b9\uff08\u51bb\u7ed3\uff0c\u5171\u4e09\u4e2a\uff09**\uff1a\u2460 \u5cf0\u503c\u5185\u5b58\uff08CPU\uff1aRSS \u5cf0\u503c + \u5206\u914d\u6b21\u6570\uff09\uff1b\u2461 \u5355\u6b65\u65f6\u95f4\u4e2d\u4f4d\u6570\uff1b\u2462 \u76f8\u5bf9\u8bef\u5dee\u3002\u5176\u4f59\u5168\u90e8\u4e3a\u6b21\u8981/\u63a2\u7d22\u6027\u3002\n\n**\u6570\u503c\u7a33\u5b9a\u6027\u5224\u636e\uff08\u7814\u7a76\u65b9\u88c1\u5b9a\uff0c\u9010\u5b57\u91c7\u7eb3\u5e76\u6536\u7d27\uff09\uff1a**\n- \u4e3b\u5224\u636e\uff1a\u540c\u79cd\u5b50\u914d\u5bf9\u4e0b\uff0c\u5404\u81c2\u5916\u5c42\u68af\u5ea6\u5bf9 float64 \u53c2\u8003\uff08T1 \u53e6\u7528\u89e3\u6790\u89e3\u6821\u9a8c\uff1b\u82e5\u9700\u66f4\u9ad8\u7cbe\u5ea6\uff0c\u6267\u884c\u73af\u5883\u5141\u8bb8\u65f6\u4ee5 mpmath \u4ea4\u53c9\u9a8c\u8bc1\u3010mpmath \u53ef\u5f97\u6027\u5c5e\u6267\u884c\u671f\u68c0\u67e5\u9879\u3011\uff09\u7684\u76f8\u5bf9 L2 \u8bef\u5dee\uff1b\u62a5\u544a\u914d\u5bf9\u5dee\u503c\u4e2d\u4f4d\u6570 + percentile bootstrap\uff0810\u2074 \u6b21\u91cd\u91c7\u6837\uff0995% CI\uff1b\u4ec5\u5f53 CI \u4e0d\u542b 0 \u4e14\u6240\u6709\u91cd\u542f\u7684\u65b9\u5411\u4e00\u81f4\u65f6\uff0c\u65b9\u53ef\u79f0\"\u66f4\u7a33\u5b9a\"\u3002\n- \u6536\u7d27\u4e00\uff1a\u4e24\u4fa7\u5747 NaN/Inf \u7684\u8fd0\u884c\u5254\u9664\u540e\u5355\u72ec\u62a5\u544a\u53d1\u751f\u7387\u5e76\u6309\u914d\u7f6e\u5206\u5c42\uff1b\u4efb\u4e00\u4fa7\u7f3a\u5931\u7387 >10% \u2192 \u8be5\u914d\u7f6e\u5224\"\u4e0d\u53ef\u6bd4\"\uff0c\u4e0d\u5f97\u8868\u8ff0\u4e3a\"\u66f4\u7a33\"\u3002\n- \u6536\u7d27\u4e8c\uff1a\u7a33\u5b9a\u6027\u7ed3\u8bba\u5fc5\u987b\u9644\u5185\u3001\u5916\u5c42\u6b65\u957f\u5404 \u22654 \u4e2a\u91cf\u7ea7\u70b9\u7684\u654f\u611f\u6027\u626b\u63cf\u4e0e\u826f\u6001/\u75c5\u6001\u6761\u4ef6\u6570\u5206\u5c42\uff0c\u4e8c\u8005\u7f3a\u4e00\u5219\u8be5\u7ed3\u8bba\u4ec5\u9650\u6240\u6d4b\u914d\u7f6e\uff0c\u4e0d\u5916\u63a8\u3002\n\n**\u65f6\u95f4\u4e0e\u5185\u5b58\uff1a** \u6bcf\u914d\u7f6e 50 \u6b21\u91cd\u590d \u00d7 \u22653 \u6b21\u72ec\u7acb\u8fdb\u7a0b\u91cd\u542f\uff1b\u5148\u5728\u91cd\u542f\u5185\u53d6\u4e2d\u4f4d\u6570\uff0c\u518d\u5bf9\u91cd\u542f\u914d\u5bf9\u7b97 log-ratio\uff1b\u62a5\u544a\u8868\u6a21\u677f\uff1a\n\n| \u914d\u7f6e | \u81c2\u5bf9 | \u6307\u6807 | \u4e2d\u4f4d\u6570[IQR]\uff08\u5404\u91cd\u542f\uff09 | HL \u4f30\u8ba1\u914d\u5bf9\u5dee | log-ratio \u5747\u503c | bootstrap 95% CI | \u65b9\u5411\u4e00\u81f4\u6027(3/3?) |\n|---|---|---|---|---|---|---|---|\n\n\u6570\u503c\u6307\u6807\u6bcf\u914d\u7f6e \u226510 \u79cd\u5b50\uff1b\u6548\u5e94\u91cf\u7528 Hodges\u2013Lehmann + \u5e73\u5747 log-ratio\uff1b\u7981\u6b62\u5355\u6b21\u8fd0\u884c\u4e0b\u7ed3\u8bba\uff1b\u79cd\u5b50\u7ea7\u539f\u59cb\u6570\u636e\u5168\u90e8\u843d\u76d8\u3002\u591a\u91cd\u6bd4\u8f83\uff1a\u4e09\u4e2a\u4e3b\u7ec8\u70b9\u5404\u81ea\u72ec\u7acb\u5224\u5b9a\uff0c\u6b21\u8981\u6307\u6807\u53ea\u505a\u63cf\u8ff0\u6027\u5448\u73b0\u5e76\u6807\u6ce8\u63a2\u7d22\u6027\u3002\n\n**\u505c\u6b62\u89c4\u5219\uff08\u4fe1\u53f7\u4f4e\u4e8e\u566a\u58f0\uff09\uff1a** \u8bd5\u70b9\u9636\u6bb5\uff083 \u914d\u7f6e \u00d7 5 \u79cd\u5b50\uff09\u4f30\u8ba1\u914d\u5bf9\u5dee\u7684 HL \u4e0e\u566a\u58f0 SD\uff1b\u82e5\u4e3b\u6307\u6807 |HL| < \u9884\u6ce8\u518c\u6700\u5c0f\u53ef\u68c0\u6548\u5e94 \u03b4_min\uff08\u65f6\u95f4/\u5185\u5b58\uff1alog-ratio 0.10\uff0c\u5373\u7ea6 10%\uff1b\u76f8\u5bf9\u8bef\u5dee\uff1a0.05 \u7edd\u5bf9\u503c\uff09\u4e14 95% CI \u5bbd\u5ea6 > 2\u00d7|HL|\uff0c\u5219\uff1a\u5148\u5347\u89c4\u6a21\u4e00\u6863\u91cd\u4f30\u4e00\u6b21\uff1b\u4ecd\u4e0d\u6ee1\u8db3 \u2192 \u8be5\u914d\u7f6e\u62a5\"\u5728\u5f53\u524d\u89c4\u6a21\u4e0b\u4e0d\u53ef\u533a\u5206\"\uff0c\u7981\u6b62\u7ed9\u51fa\u65b9\u5411\u6027\u8868\u8ff0\u3002\n\n**\u53ea\u80fd\u5199\u6210\"\u8bbe\u8ba1\u53ef\u56de\u7b54\u7684\u95ee\u9898\"\u3001\u4e0d\u5f97\u5199\u6210\u53d1\u73b0\u7684\u6761\u76ee\uff08\u5f53\u524d\u8bc1\u636e\u72b6\u6001\uff09\uff1a** A \u662f\u5426\u66f4\u5feb\uff1bA \u662f\u5426\u5cf0\u503c\u5185\u5b58\u66f4\u4f4e\uff1bA \u662f\u5426\u76f8\u5bf9\u8bef\u5dee\u66f4\u5c0f\uff1b\u6548\u5e94\u662f\u5426\u968f K/\u5bbd\u5ea6\u589e\u957f\uff1b\u6548\u5e94\u6765\u81ea\"\u663e\u5f0f\u5c55\u5f00\"\u8fd8\u662f\"TorchOpt \u5b9e\u73b0\"\uff08\u7531 B2/C \u81c2\u4e09\u89d2\u5b9a\u4f4d\uff09\u3002\u76ee\u524d\u56db\u6761\u5168\u90e8\u65e0\u8bc1\u636e\u3002\n\n---\n\n## 7. \u53ef\u884c\u6027\u4e0e\u6267\u884c\u524d\u68c0\u67e5\u8868\uff08\u5982\u5b9e\u58f0\u660e\uff09\n\n**\u4e0d\u53ef\u6267\u884c\u8fb9\u754c\uff1a** \u5f53\u524d\u73af\u5883\uff08\u65e0\u7f51\u7edc\u3001torch/torchopt/numpy \u5747\u672a\u5b89\u88c5\u3001Python 3.14.4\u3001\u65e0 GPU\uff09\u4e0b\u8fde\u4e00\u884c\u5bf9\u6bd4\u4ee3\u7801\u90fd\u65e0\u6cd5\u8fd0\u884c\u2014\u2014\u4e00\u884c\u4f9d\u8d56 import torch \u7684\u9aa8\u67b6\u4ee3\u7801\u90fd\u4e0d\u6210\u7acb\u3002\u6545\u672c\u4ea4\u4ed8\u7269\u6b62\u4e8e\u8bbe\u8ba1\uff1b\u672c\u6587\u6863\u4e0d\u5b58\u5728\u4efb\u4f55\u8fd0\u884c\u8bb0\u5f55\u3002\n\n**\u6267\u884c\u524d\u68c0\u67e5\u8868\uff08\u987a\u5e8f\u6267\u884c\uff0c\u5168\u8fc7\u624d\u5141\u8bb8\u8dd1\u6570\uff09\uff1a**\n1. \u7f51\u7edc\u6216\u79bb\u7ebf wheel \u7f13\u5b58\u53ef\u7528\uff1b\n2. Python \u7248\u672c \u2208 torch \u5b98\u65b9\u652f\u6301\u8303\u56f4\uff08\u5efa\u8bae 3.10\u20133.12 \u72ec\u7acb conda \u73af\u5883\u30103.14 \u5927\u6982\u7387\u4e0d\u53d7\u652f\u6301\u2014\u2014\u6b64\u5224\u65ad\u672c\u8eab\u662f\u63a8\u6d4b\uff0c\u4ee5\u68c0\u67e5 3 \u4e3a\u51c6\u3011\uff09\uff1b\n3. `pip install torch==<X>` \u540e `import torch; torch.__version__` \u6210\u529f\uff0c\u8bb0\u5f55\u7248\u672c\uff1b\n4. TorchOpt \u6e90\u7801 checkout\uff08git \u6216 tarball\uff09\uff0c`pip install -e .`\uff0c`dir(torchopt)` \u6210\u529f\uff1btorchopt\u2194torch \u7248\u672c\u914d\u5bf9\u8bb0\u5f55\u5728\u6848\uff1b\n5. \u5b8c\u6210 \u00a71 Gate 0 \u5168\u90e8\u6458\u5f55\u5e76\u5f52\u6863\u4e3a\u6587\u672c\u6587\u4ef6\uff08\u539f\u6587\u5f15\u7528+commit hash\uff09\uff1b\n6. numpy\uff08\u5fc5\u9700\uff09\u3001mpmath\uff08T1 \u9ad8\u7cbe\u5ea6\u6821\u9a8c\u7528\uff09\u3001matplotlib/seaborn\uff08\u62a5\u544a\u7528\uff09\u5c31\u4f4d\uff1b\n7. \u7ed1\u6838\u4e0e\u7ebf\u7a0b\u53c2\u6570\u5199\u6b7b\u5165\u914d\u7f6e\u6587\u4ef6\u5e76\u5165\u5e93\uff1b\n8. CPU-only \u8bd5\u70b9\uff1aT1 \u4e0e T2 \u6700\u5c0f\u6863\u5404 3 \u79cd\u5b50\uff0c\u4f30\u7b97\u566a\u58f0 SD \u4e0e\u6700\u5c0f\u53ef\u68c0\u89c4\u6a21\uff0c\u636e\u6b64\u786e\u5b9a\u6b63\u5f0f\u89c4\u6a21\u4e0b\u9650\uff08\u4f30\u8ba1\u91cf\u4e0e\u89c4\u5219\u89c1 \u00a76 \u505c\u6b62\u89c4\u5219\uff09\uff1b\n9. \u663e\u5b58\u6307\u6807\u9000\u5316\u58f0\u660e\uff1a\u65e0 GPU \u65f6\u4e3b\u7ec8\u70b9\u2460\u81ea\u52a8\u91c7\u7528 RSS \u5cf0\u503c+\u5206\u914d\u8ba1\u6570\u53e3\u5f84\uff0c\u62a5\u544a\u6587\u5b57\u5fc5\u987b\u5199\u660e\u8be5\u53e3\u5f84\u4e0e CUDA \u663e\u5b58\u53e3\u5f84\u4e0d\u53ef\u76f4\u63a5\u4e92\u6362\u3002\n\n---\n\n## 8. \u7ed3\u8bba\u6a21\u677f\uff08\u53cc\u5411\u53ef\u89e3\u91ca\u6027\uff0c\u663e\u5f0f\u58f0\u660e\u4e0d\u9884\u8bbe\u65b9\u5411\uff09\n\u6700\u7ec8\u7ed3\u8bba\u56db\u9009\u4e00\uff08\u6216\u7ec4\u5408\uff09\uff0c\u5404\u914d\u65e2\u5b9a\u89e3\u91ca\u6bb5\uff1a\n- G1 A \u66f4\u5feb\u4e14\u66f4\u7a33\uff1a\u4ee5\u4e2d\u95f4\u91cf\u590d\u7528\u51cf\u5c11\u5206\u914d/\u53cd\u4f20\u56fe\u89c4\u6a21\u89e3\u91ca\uff0c\u9700 B2/C \u5b9a\u4f4d\u6765\u6e90\uff1b\n- G2 A \u66f4\u5feb\u4f46\u66f4\u4e0d\u7a33\uff1a\u5141\u8bb8\u7ed3\u8bba\u4e3a\"\u901f\u5ea6\u6362\u7a33\u5b9a\u6027\"\uff0c\u68c0\u67e5\u5c55\u5f00\u987a\u5e8f\u5f15\u5165\u7684\u8bef\u5dee\u7d2f\u79ef\uff08B2 \u5e94\u590d\u73b0\u540c\u578b\u683c\u5c40\uff0c\u5426\u5219\u5f52\u56e0\u5b9e\u73b0\u7ec6\u8282\uff09\uff1b\n- G3 A \u66f4\u7a33\u4f46\u66f4\u6162\uff1a\u5141\u8bb8\u7ed3\u8bba\u4e3a\"\u8bef\u5dee\u7ed3\u6784\u66f4\u4f18\u4f46\u5f00\u9500\u66f4\u9ad8\"\uff1b\n- G4 \u65e0\u5dee\u5f02/\u4e0d\u53ef\u533a\u5206\uff1a\u4ee5 N \u81c2\u901a\u8fc7\u4e3a\u524d\u63d0\uff0c\u62a5\u7b49\u4ef7\u533a\u95f4\u5185\u7ed3\u8bba\u3002\n\u4efb\u4e00\u683c\u5c40\u5747\u4e0d\u5f97\u5916\u63a8\u81f3\u672a\u6d4b\u7684\u89c4\u6a21\u6863\u3001\u6761\u4ef6\u6570\u5c42\u6216\u6b65\u957f\u533a\u95f4\uff08\u00a76 \u6536\u7d27\u4e8c\uff09\u3002\n\n---\n\n## 9. \u5047\u8bbe\u6e05\u5355\uff08\u4e0e\u4efb\u52a1\u8981\u6c42\u5206\u79bb\uff0c\u672a\u6838\u5b9e\u9879\u6c47\u603b\uff09\n1.\u3010\u5047\u8bbe\u3011\u663e\u5f0f\u5fae\u5206\u5165\u53e3\u5373 torchopt.grad/value_and_grad\uff0c\"\u590d\u7528\u4e2d\u95f4\u91cf/\u6700\u5c0f\u5316\u5206\u914d/\u7a33\u5b9a\u6027\u6536\u76ca\"\u4e3a\u5b98\u65b9\u5ba3\u79f0\u2014\u2014\u5747\u5f85 Gate 0 \u6838\u5b9e\u3002\n2.\u3010\u5047\u8bbe\u3011arXiv:2404.16815 \u4e3a\u5bf9\u5e94\u8bba\u6587\u53ca\u7248\u672c\u2014\u2014\u672a\u6838\u5b9e\u3002\n3.\u3010\u5047\u8bbe\u3011PyTorch \u5b98\u65b9\u6587\u6863\u542b bilevel\uff08double-backward vs unfold\uff09\u793a\u4f8b\u53ef\u4f5c T3 \u8303\u5f0f\u2014\u2014\u672a\u672c\u5730\u6838\u5b9e\u3002\n4.\u3010\u5047\u8bbe\u3011Python 3.14 \u4e0e torch \u8f6e\u5b50\u4e0d\u517c\u5bb9\u2014\u2014\u63a8\u6d4b\uff0c\u4ee5\u68c0\u67e5\u8868\u7b2c 2/3 \u6b65\u5b9e\u6d4b\u4e3a\u51c6\u3002\n5.\u3010\u5047\u8bbe\u3011CPU \u73a9\u5177\u89c4\u6a21\u8db3\u4ee5\u4ea7\u751f\u53ef\u68c0\u4fe1\u53f7\u2014\u2014\u672a\u77e5\uff0c\u4ee5\u8bd5\u70b9\u4f30\u7b97\uff0c\u4e14\u6709\u505c\u6b62\u89c4\u5219\u515c\u5e95\u3002\n6.\u3010\u5047\u8bbe\u3011K-FAC \u81c2\u53ef\u884c\u2014\u2014\u82e5 TorchOpt \u65e0\u5bf9\u5e94\u5b9e\u73b0\u5373\u5254\u9664\u3002\n7. \u7814\u7a76\u65b9\u88c1\u5b9a\u5df2\u56fa\u5b9a\uff08\u975e\u5047\u8bbe\uff09\uff1a\u7a33\u5b9a\u6027\u64cd\u4f5c\u5b9a\u4e49\u3001\u4e09\u4e3b\u7ec8\u70b9\u51bb\u7ed3\u3001\u65b9\u5411\u4e0d\u9884\u8bbe\u3001\u96f6\u5047\u8bbe\u81c2\u5f3a\u5236\u3001torch.func \u7b2c\u4e09\u65b9\u5f3a\u5236\u3001\u226510 \u79cd\u5b50\u4e0e\u914d\u5bf9\u6548\u5e94\u91cf\u89c4\u8303\u3002", "evidence": "\u8bbe\u8ba1\u4f9d\u636e\u5168\u90e8\u6765\u81ea\uff1a(1) \u524d\u8f6e\u672c\u5730\u76d8\u70b9\u4e8b\u5b9e\u2014\u2014\u5de5\u4f5c\u533a\u4ec5 task.json\u3001\u65e0 TorchOpt \u8d44\u6599\uff1bPython 3.14.4\uff1btorch/torchopt/numpy/jax \u5747\u672a\u5b89\u88c5\uff1b\u65e0 GPU/\u65e0\u7f51\u7edc/224 \u6838\uff1btask.json \u81ea\u8ff0 design-only\u3002(2) \u7814\u7a76\u65b9\u672c\u8f6e\u88c1\u5b9a\u6587\u672c\u2014\u2014\u7a33\u5b9a\u6027\u4e3b\u5224\u636e+\u4e24\u6761\u6536\u7d27\u3001\u4e09\u4e3b\u7ec8\u70b9\u51bb\u7ed3\u3001\u53cc\u5411\u7ed3\u8bba\u6a21\u677f\u3001torch.func \u7b2c\u4e09\u65b9\u81c2\u4e0e\u96f6\u5047\u8bbe\u81c2\u5f3a\u5236\u3001\u5355\u56e0\u7d20\u6e05\u5355\u3001\u226510 \u79cd\u5b50\u4e0e\u914d\u5bf9\u6548\u5e94\u91cf\u3001Gate 0 \u524d\u7f6e\u6838\u5b9e\u4e0e\u964d\u7ea7\u5199\u6cd5\u8981\u6c42\uff0c\u5747\u5df2\u9010\u6761\u5199\u5165 \u00a71/\u00a72/\u00a75/\u00a76/\u00a78\u3002(3) \u516c\u5f00\u6587\u6863\u77e5\u8bc6\uff08\u5df2\u6807\u3010\u5047\u8bbe\u3011\uff09\uff1aTorchOpt \u4ed3\u5e93\u7ed3\u6784\uff08torchopt/api.py\u3001docs \u6559\u7a0b\u3001arXiv:2404.16815\uff09\u3001torch.autograd.grad(create_graph=True)\u3001torch.func \u7ec4\u5408\u5b50\u3001PyTorch bilevel double-backward vs unfold \u8303\u5f0f\u3002\u65e0\u865a\u6784\u7ed3\u679c\u3001\u5f15\u7528\u7f16\u53f7\u6216\u8fd0\u884c\u8bb0\u5f55\uff1b\u6587\u6863\u660e\u786e\u58f0\u660e\u5f53\u524d\u8bc1\u636e\u72b6\u6001\u4e0b\u56db\u9879\u6838\u5fc3\u95ee\u9898\u5747\"\u65e0\u8bc1\u636e\"\u3002", "assumptions": ["TorchOpt \u663e\u5f0f\u5fae\u5206\u5165\u53e3\u7684\u771f\u5b9e\u540d\u79f0/\u7b7e\u540d\u53ca\u201c\u4e2d\u95f4\u91cf\u590d\u7528\u201d\u5f00\u5173\u662f\u5426\u5b58\u5728\uff0c\u5f85 Gate 0 \u4ee5\u6e90\u7801/\u5b98\u65b9\u6587\u6863\u6838\u5b9e\uff1b\u5f53\u524d\u5199\u6cd5\u4ec5\u4e3a\u5360\u4f4d", "arXiv:2404.16815 \u4f5c\u4e3a TorchOpt \u8bba\u6587\u7684\u7f16\u53f7\u4e0e\u8bbe\u8ba1\u610f\u56fe\u8868\u8ff0\u672a\u6838\u5b9e\uff0c\u4ec5\u4f5c\u5f85\u67e5\u8bc1\u76ee\u6807", "PyTorch \u5b98\u65b9 bilevel\uff08double-backward vs unfold\uff09\u793a\u4f8b\u7684\u5b58\u5728\u4e0e\u5185\u5bb9\u672a\u672c\u5730\u6838\u5b9e\uff0cT3 \u4f9d\u8d56\u4e4b", "Python 3.14 \u4e0e torch \u8f6e\u5b50\u517c\u5bb9\u6027\u3001torchopt \u5b89\u88c5\u53ef\u884c\u6027\u5747\u5c5e\u63a8\u6d4b\uff0c\u4ee5\u6267\u884c\u524d\u68c0\u67e5\u8868\u5b9e\u6d4b\u4e3a\u51c6", "CPU \u73a9\u5177\u89c4\u6a21\u80fd\u5426\u4ea7\u751f\u8d85\u8fc7\u566a\u58f0\u7684\u4fe1\u53f7\u672a\u77e5\uff0c\u7531\u8bd5\u70b9\u4f30\u7b97+\u505c\u6b62\u89c4\u5219\u63a7\u5236", "\u6267\u884c\u671f\u53ef\u83b7\u5f97 mpmath \u7b49\u9ad8\u7cbe\u5ea6\u6821\u9a8c\u4f9d\u8d56\uff08\u82e5\u4e0d\u53ef\u5f97\uff0cT1 \u4ee5 float64 \u89e3\u6790\u89e3\u4e3a\u53c2\u8003\u4e0a\u9650\uff0