b\u5b58\u5728\u6027\u672a\u672c\u5730\u6838\u5b9e\uff0c\u5c5e\u5047\u8bbe\u3011\uff09 | \u5f3a | float64 \u6570\u503c\u53c2\u8003 | \u540c T1 | \u4e0e\u516c\u5f00\u6587\u6863\u8bbe\u7f6e\u540c\u6784\uff0c\u4fbf\u4e8e\u5916\u90e8\u5bf9\u7167 |\n| T4\uff08\u53ef\u9009\uff0cGate 0 \u540e\u53d1\u73b0 TorchOpt \u4fa7\u65e0\u5bf9\u5e94\u5b9e\u73b0\u5373\u5254\u9664\uff09\u534f\u65b9\u5dee/\u66f2\u7387\u7c7b\u7b97\u5b50\uff08K-FAC \u98ce\u683c Kronecker \u56e0\u5b50\u7684\u7279\u5f81\u5206\u89e3\uff09 | \u4e2d | float64 \u53c2\u8003 | \u5c42\u5bbd {64, 256, 1024} | \u4e0d\u5f97\u6253\u7a7a\u9776\uff1a\u4ec5\u5f53 A \u81c2\u6709\u771f\u5b9e\u5bf9\u5e94\u8def\u5f84\u624d\u542f\u7528 |\n| N \u96f6\u5047\u8bbe\u81c2\uff1a\u5408\u6210/\u5c0f\u56fe\u50cf\u4e00\u9636 MLP+SGD | \u65e0 | \u4e0d\u9700\u8981 | \u5bbd\u5ea6 {128, 512} | \u5f3a\u5236\u9879\uff0c\u89c1 \u00a75 |\n\n\u89c4\u6a21\u62a5\u544a\u89c4\u8303\uff1a\u5bf9 K\u3001\u5bbd\u5ea6\u4e24\u4e2a\u8f74\u5404\u51fa\u4e00\u6761 log-log \u7684\u300c\u6307\u6807~\u89c4\u6a21\u300d\u66f2\u7ebf\uff08\u5185\u5b58\u3001\u65f6\u95f4\u5404\u4e00\uff09\uff0c\u6bd4\u8f83\u5404\u81c2\u659c\u7387\u4e0e\u622a\u8ddd\uff1b\u7981\u6b62\u53ea\u62a5\u5355\u70b9\u3002CPU-only \u65f6 T2 \u53d6\u5c0f\u6863\u4f18\u5148\uff08\u5bbd\u5ea6 \u2264128\u3001K \u226410\u3001Omniglot \u6682\u7f13\uff09\uff0c\u89c4\u6a21\u4e0b\u9650\u4f30\u7b97\u89c1 \u00a77 \u68c0\u67e5\u8868\u3002\n\n---\n\n## 5. \u63a7\u5236\u4e0e\u96f6\u5047\u8bbe\u81c2\uff08\u542b\u91cf\u5316\u901a\u8fc7\u5bb9\u5dee\uff09\n\n- N \u81c2\u901a\u8fc7\u5224\u636e\uff08\u9884\u6ce8\u518c\uff09\uff1a\u5728 N \u4efb\u52a1\u4e0a\uff0c\u914d\u5bf9\uff08\u540c\u79cd\u5b50\uff09\u7684 A/B1 \u4e0e C/B1 \u65f6\u95f4\u6bd4\u503c\u7684 bootstrap 95% CI \u5fc5\u987b\u6574\u4f53\u843d\u5165\u7b49\u4ef7\u533a\u95f4 [1/1.05, 1.05]\uff08TOST\uff0c\u5bf9\u6570\u5c3a\u5ea6\u8fb9\u9645 \u00b1ln 1.05\uff09\uff1b\u5cf0\u503c RSS \u76f8\u5bf9\u5dee CI \u843d\u5165 \u00b12% \u6216 < 2\u00d7\u79cd\u5b50\u95f4\u6807\u51c6\u5dee\uff08\u53d6\u8f83\u5bbd\u8005\uff09\u3002\u82e5\u4e0d\u901a\u8fc7 \u2192 \u5224\u5b9a harness/\u5165\u53e3\u5305\u88c5\u672c\u8eab\u6709\u5f00\u9500\uff0c\u6682\u505c\u4e3b\u5b9e\u9a8c\uff0c\u5148\u5f52\u56e0\uff08\u5982\u8f93\u5165\u683c\u5f0f\u8f6c\u6362\u3001pytree \u62f7\u8d1d\uff09\uff0c\u5e76\u628a\u8fd9\u4e2a\u5f00\u9500\u4f5c\u4e3a\u72ec\u7acb\u53d1\u73b0\u5355\u5217\u3002\n- \u524d\u5411\u4e00\u81f4\u6027\u65ad\u8a00\uff1a\u6240\u6709\u81c2\u5728\u6d4b\u524d assert \u524d\u5411\u8f93\u51fa\u4e0e B1 \u5728 float64 \u4e0b\u6700\u5927\u7edd\u5bf9\u5dee \u2264 1e-12\u3002\n- \u987a\u5e8f\u504f\u501a\u63a7\u5236\uff1a\u914d\u7f6e\u5185\u81c2\u7684\u6267\u884c\u987a\u5e8f\u7528\u62c9\u4e01\u65b9\u8f6e\u6362\uff1b\u8fdb\u7a0b\u91cd\u542f\u6253\u6563\u81c2\u987a\u5e8f\u3002\n- \u7ebf\u7a0b/\u7ed1\u6838/\u9891\u7387\u566a\u58f0\uff1a\u56fa\u5b9a\u7ebf\u7a0b\u6570\u3001\u7ed1\u6838\u96c6\u5408\u8bb0\u5f55\u5165\u65e5\u5fd7\uff1b\u6bcf\u6b21\u91cd\u542f\u8bb0\u5f55 CPU \u9891\u7387\u4e0e\u8d1f\u8f7d\u5feb\u7167\u3002\n\n---\n\n## 6. \u7edf\u8ba1\u8ba1\u5212\u4e0e\u5224\u636e\uff08\u542b\u7814\u7a76\u65b9\u88c1\u5b9a\u539f\u6587\u7684\u5de5\u7a0b\u5316\u843d\u5730\uff09\n\n**\u4e3b\u7ec8\u70b9\uff08\u51bb\u7ed3\uff0c\u5171\u4e09\u4e2a\uff09**\uff1a\u2460 \u5cf0\u503c\u5185\u5b58\uff08CPU\uff1aRSS \u5cf0\u503c + \u5206\u914d\u6b21\u6570\uff09\uff1b\u2461 \u5355\u6b65\u65f6\u95f4\u4e2d\u4f4d\u6570\uff1b\u2462 \u76f8\u5bf9\u8bef\u5dee\u3002\u5176\u4f59\u5168\u90e8\u4e3a\u6b21\u8981/\u63a2\u7d22\u6027\u3002\n\n**\u6570\u503c\u7a33\u5b9a\u6027\u5224\u636e\uff08\u7814\u7a76\u65b9\u88c1\u5b9a\uff0c\u9010\u5b57\u91c7\u7eb3\u5e76\u6536\u7d27\uff09\uff1a**\n- \u4e3b\u5224\u636e\uff1a\u540c\u79cd\u5b50\u914d\u5bf9\u4e0b\uff0c\u5404\u81c2\u5916\u5c42\u68af\u5ea6\u5bf9 float64 \u53c2\u8003\uff08T1 \u53e6\u7528\u89e3\u6790\u89e3\u6821\u9a8c\uff1b\u82e5\u9700\u66f4\u9ad8\u7cbe\u5ea6\uff0c\u6267\u884c\u73af\u5883\u5141\u8bb8\u65f6\u4ee5 mpmath \u4ea4\u53c9\u9a8c\u8bc